      "path": "packages/dsh-plugin/package.json",
      "content": "{\n  \"name\": \"@taxueseek/argo-dsh\",\n  \"version\": \"2.10.1\",\n  \"description\": \"Argo 阿尔戈 — DSH plugin：argo 原生搜索/抓取工具 + web_search seam + wide_research 编排；自带设置页（接入/工具/API 密钥/研究/高级）；argo MCP 19 工具全量面按需挂载。安装：dsh plugin --profile web add @taxueseek/argo-dsh（或从 GitHub main 装：dsh plugin --profile web add \\\"github:taxueseek/argo#main&path:packages/dsh-plugin\\\"）\",\n  \"license\": \"Apache-2.0\",\n  \"type\": \"module\",\n  \"main\": \"./dsh/index.js\",\n  \"exports\": {\n    \".\": \"./dsh/index.js\",\n    \"./dsh\": \"./dsh/index.js\",\n    \"./client\": \"./dsh/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"dsh\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ]\n    }\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"check\": \"node --check dsh/index.js && node --check dsh/runner.js && node --check dsh/wide-research.js && node --check dsh/diagnostics.js && node --check dsh/client.js\",\n    \"test\": \"node --test test/*.test.js\"\n  }\n}\n"
